function saleReturns(s){return (s.returns||[]).filter(r=>!r.voided);}
function returnedQty(s){return saleReturns(s).reduce((n,r)=>n+Number(r.qty),0);}
function saleQuantity(s){return Number(s.qty||0)-returnedQty(s);}
function originalSaleTotal(s){return cents(Number(s.qty||0)*Number(s.unitPrice||0))/100;}
function saleTotal(s){return (cents(originalSaleTotal(s))-saleReturns(s).reduce((n,r)=>n+cents(r.amount),0))/100;}
function allReturns(){return db.sales.filter(s=>!s.voided).flatMap(s=>saleReturns(s).map(r=>({...r,saleId:s.id,productId:s.productId,customer:s.customer})));}

