function receivablesView(){let rows=invoiceRows().filter(x=>arFilter==='Priority'||arFilter==='All'||x.status===arFilter||x.bucket===arFilter);rows.sort((a,b)=>arPriority(a)-arPriority(b)||(a.status==='Credit'?a.balance-b.balance:b.balance-a.balance)||((a.age||-1)<(b.age||-1)?1:-1));let opts=['Priority','All','Due','Credit','Paid','0-30 Days','31-60 Days','61-90 Days','90+ Days','Unknown Date'];return `<div class="card hero"><h1>Receivables Workspace</h1><p class="muted">Credits and balances requiring attention appear first.</p><div class="actions">${opts.map(x=>`<button class="${arFilter===x?'active':''}" onclick="setARFilter('${x}')">${x}</button>`).join('')}</div></div><div class="card">${empty(rows)}${rows.map(x=>`<div class="row"><div><b>${html(x.customer)} · ${html(x.id)}</b><p>${html(pname(x.productId))} · ${html(x.date||'Unknown date')} · ${html(x.bucket)}</p></div><div class="actions"><span class="tag">${x.status==='Credit'?money(Math.abs(x.balance))+' credit':x.status==='Due'?money(x.balance)+' due':'Paid'}</span><button onclick="openCustomer('${escAttr(x.customer)}')">Customer</button><button onclick="openSaleReturn(${actionArg(x.id)})">Return items</button>${(x.returns||[]).length?actionButton('Return history',`openReturnHistory(${actionArg(x.id)})`):''}${x.status==='Credit'?`<button class="primary" onclick="manageCredit('${escAttr(x.customer)}')">Manage Credit</button>`:''}${x.balance>0?`<button onclick="createInvoice('${escAttr(x.id)}')">Create Invoice / PDF</button><button class="primary" onclick="pay('${escAttr(x.id)}',${x.balance})">Payment</button>`:''}</div></div>`).join('')}</div>`}
