function customerDetail(name){let ss=invoiceRows().filter(x=>x.customer===name),ids=ss.map(x=>x.id),pp=db.payments.filter(p=>!p.voided&&ids.includes(p.saleId)),cc=db.claims.filter(c=>!c.voided&&c.customer===name),inv=ss.reduce((n,x)=>n+x.total,0),paid=pp.reduce((n,x)=>n+Number(x.amount||0),0);return `<div class="card hero"><div class="row"><div><h2>${html(name)}</h2><p>${ss.length} invoices · ${unitCount(ss)} units purchased · ${pp.length} payments · ${cc.length} warranty claims</p></div>${customerCredit(name)>0?`<button class="primary" onclick="manageCredit('${escAttr(name)}')">Manage Credit</button>`:''}<button onclick="closeCustomer()">Back to Customers</button></div><div class="grid g3">${metric('Invoiced',money(inv))}${metric('Paid',money(paid))}${metric('Balance Due',money(sumMoney(ss,x=>Math.max(0,x.balance))))}${metric('Customer Credit',money(customerCredit(name)))}</div></div>${creditLedger(name)}<div class="grid g2"><div class="card"><h3>Invoices</h3><button onclick="createStatement(${actionArg(name)})">Customer statement / PDF</button>${empty(ss)}${ss.map(x=>`<div class="row"><div><b>${html(x.id)}</b><p>${html(x.date||'Unknown date')} · ${html(x.bucket)}</p></div><span class="tag">${x.status==='Credit'?money(Math.abs(x.balance))+' credit':money(x.balance)+' due'}</span><button onclick="openSaleReturn(${actionArg(x.id)})">Return items</button>${(x.returns||[]).length?actionButton('Return history',`openReturnHistory(${actionArg(x.id)})`):''}${actionButton('Invoice / PDF',`createInvoice(${actionArg(x.id)})`)}${actionButton('Record payment',`pay(${actionArg(x.id)})`)}${actionButton('View payments',`openInvoicePayments(${actionArg(x.id)})`)}</div>`).join('')}</div><div class="card"><h3>Payments</h3>${empty(pp)}${pp.map(x=>`<div class="row"><div><b>${html(x.method||'Unknown')}</b><p>${html(x.date||'Unknown date')} · ${html(x.saleId)}</p></div><strong>${money(x.amount)}</strong>${paymentActions(x)}</div>`).join('')}</div></div><div class="card"><h3>Customer Notes & Collections</h3><p>${html(customerMeta(name).notes||'No customer notes.')}</p><div class="actions">${(customerMeta(name).tags||[]).map(x=>`<span class="tag">${html(x)}</span>`).join('')}<button onclick="editCustomerNotes('${escAttr(name)}')">Edit Notes / Tags</button><button onclick="addCollectionNote('${escAttr(name)}')">Add Collection Note</button></div>${(customerMeta(name).collections||[]).map(x=>`<div class="row"><div><b>${html(x.method)}</b><p>${html(x.date)} · ${html(x.note)}</p></div></div>`).join('')}${attachmentsView('customer',name)}</div><div class="card"><h3>Warranty</h3>${empty(cc)}${cc.map(x=>`<div class="row"><div><b>${html(pname(x.productId))}</b><p>${html(x.status)} · ${html(x.date||'Unknown date')}</p></div><span>${money(x.approvedCredit||0)} approved</span>${actionButton('Claim details',`openClaim(${actionArg(x.id)})`)}</div>`).join('')}</div>`}
