function addAttachment(recordType,recordId,e){let file=e.target.files?.[0];if(!file)return;if(file.size>1500000)return alert('Attachment must be smaller than 1.5 MB.');let reader=new FileReader();reader.onload=()=>{db.attachments=db.attachments||[];db.attachments.push({id:uid('ATT'),recordType,recordId,name:file.name,type:file.type,size:file.size,data:reader.result,date:new Date().toISOString()});saveLocal('Attachment added',recordType+' '+recordId+' · '+file.name)};reader.readAsDataURL(file);e.target.value=''}
