function poSubtotal(o){return (o.lines||[]).reduce((n,l)=>n+cents(Number(l.qty||0)*Number(l.unitCost||0)),0)/100;}
function poTotal(o){return (cents(poSubtotal(o))+cents(o.shipping||0)+cents(o.fees||0)-cents(o.credit||0))/100;}
function weightedCosts(){let out={};for(let p of products()){let units=0,cost=0;for(let o of db.orders.filter(o=>!o.cancelled)){let subtotal=poSubtotal(o);for(let l of (o.lines||[]).filter(l=>l.productId===p.id)){let received=Number(l.received||0),base=received*Number(l.unitCost||0),share=subtotal>0?(Number(l.qty||0)*Number(l.unitCost||0))/subtotal:0,landed=base+(Number(o.shipping||0)+Number(o.fees||0)-Number(o.credit||0))*share*(Number(l.qty||0)?received/Number(l.qty):0);units+=received;cost+=landed}}out[p.id]=units>0?cost/units:p.cost}return out}
function csvCell(v){let x=v==null?'':String(v);if(typeof v==='string'&&/^[=+@\-\t\r]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'}
function downloadCSV(name,headers,rows){let csv=[headers.map(csvCell).join(','),...rows.map(r=>r.map(csvCell).join(','))].join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name+'-'+today()+'.csv';a.click();URL.revokeObjectURL(url)}
