function exportWarranty(){downloadCSV('warranty',['Claim ID','Date','Customer','Product','Status','Replacement Cost','Shipping','Approved Credit','Applied Credit','Remaining Credit'],db.claims.map(x=>[x.id,x.date,x.customer,pname(x.productId),x.status,x.replacementCost,x.shipping,x.approvedCredit,x.appliedCredit,Number(x.approvedCredit||0)-Number(x.appliedCredit||0)]))}
function accountantExports(){return `<div class="card"><h3>Accountant Exports</h3><p class="muted">CSV files contain all saved records in this workspace. Keep these exports private.</p><div class="actions"><button onclick="exportSales()">Sales & Profit</button><button onclick="exportReturns()">Returns CSV</button><button onclick="exportPayments()">Payments</button><button onclick="exportExpenses()">Expenses</button><button onclick="exportInventory()">Inventory Valuation</button><button onclick="exportReceivables()">Receivables</button><button onclick="exportWarranty()">Warranty Credits</button><button onclick="exportInventoryHistory()">Inventory history</button><button onclick="exportOperatingCosts()">Warranty & stock costs</button></div></div>`}

function validDate(v){let d=v?new Date(v+'T00:00:00'):null;return d&&!isNaN(d)?d:null}
function periodMatch(date,period=reportPeriod){if(period==='All Time')return true;let d=validDate(date);if(!d)return false;let now=new Date();return period==='This Month'?d.getFullYear()===now.getFullYear()&&d.getMonth()===now.getMonth():period==='This Year'?d.getFullYear()===now.getFullYear():true}
function unitCount(sales){return sales.reduce((n,s)=>n+saleQuantity(s),0)}
function transactionCount(sales){return sales.length}

function monthKey(date){let d=validDate(date);return d?d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0'):'Unknown'}
function monthlyTrend(){let map=Object.create(null);for(let s of db.sales.filter(s=>!s.voided)){let k=monthKey(s.date);if(k==='Unknown')continue;(map[k]??={revenue:0,collected:0}).revenue+=Number(s.qty||0)*Number(s.unitPrice||0)}for(const r of allReturns()){const k=monthKey(r.date);if(k!=='Unknown')(map[k]??={revenue:0,collected:0}).revenue-=r.amount;}for(let p of cashPayments()){let k=monthKey(p.date);if(k==='Unknown')continue;(map[k]??={revenue:0,collected:0}).collected+=Number(p.amount||0)}return Object.entries(map).sort((a,b)=>a[0].localeCompare(b[0])).slice(-12).map(([month,x])=>({month,...x}))}
function arAging(){let out={'0-30 Days':0,'31-60 Days':0,'61-90 Days':0,'90+ Days':0,'Unknown Date':0,'Customer Credits':0};for(let x of invoiceRows()){if(x.balance<-.009)out['Customer Credits']+=Math.abs(x.balance);else if(x.balance>.009)out[x.bucket]+=x.balance}return out}
function topCustomers(){let map=Object.create(null);for(let s of db.sales.filter(s=>!s.voided)){let x=map[s.customer]??={customer:s.customer,revenue:0,units:0};x.revenue+=saleTotal(s);x.units+=saleQuantity(s)}return Object.values(map).sort((a,b)=>b.revenue-a.revenue).slice(0,8)}
function productPerformance(){let wc=weightedCosts();return products().map(p=>{let ss=db.sales.filter(s=>!s.voided&&s.productId===p.id),units=unitCount(ss),revenue=sumMoney(ss,saleTotal);return{...p,weightedCost:wc[p.id],units,revenue,gross:revenue-units*wc[p.id],onHand:inventory().find(x=>x.id===p.id)?.onHand||0}}).sort((a,b)=>b.revenue-a.revenue)}
function forecastRows(){let cutoff=new Date();cutoff.setDate(cutoff.getDate()-90);return inventory().map(p=>{let sold90=db.sales.filter(s=>!s.voided&&s.productId===p.id&&validDate(s.date)&&validDate(s.date)>=cutoff).reduce((n,s)=>n+saleQuantity(s),0),monthly=sold90/3,months=monthly>0?p.onHand/monthly:null;return{...p,sold90,monthly,months}})}
function barRows(rows,label,value,format=money){let max=Math.max(1,...rows.map(x=>Math.abs(value(x))));return rows.map(x=>`<div class="chart-row"><div class="chart-label">${html(label(x))}</div><div class="chart-track"><div class="chart-fill ${value(x)<0?'negative':''}" style="width:${Math.max(2,Math.abs(value(x))/max*100)}%"></div></div><strong>${format(value(x))}</strong></div>`).join('')}

function setReportPeriod(x){reportPeriod=x;render()}
function reportsView(){let f=financials(),aging=arAging(),products=productPerformance(),trend=monthlyTrend(),periods=['All Time','This Year','This Month'];return `<div class="card hero"><h1>Operational Reports</h1><div class="actions"><button onclick="printReport()">Print / Save PDF</button>${periods.map(x=>`<button class="${reportPeriod===x?'active':''}" onclick="setReportPeriod('${x}')">${x}</button>`).join('')}</div></div><div class="grid g4">${metric('Revenue',money(f.revenue))}${metric('Collected',money(f.collected))}${metric('COGS Estimate',money(f.cogs))}${metric('Gross Profit',money(f.gross))}${metric('Expenses',money(f.expenseTotal))}${metric(f.unreviewedCostCount?'Provisional Net Profit':'Estimated Net Profit',money(f.net))}${metric('Net Units Sold',f.unitsSold)}${metric('Sales Transactions',f.salesTransactions)}${metric('Payments Count',f.payments.length)}</div>${operatingCostReport(f)}<div class="grid g2"><div class="card"><h3>Product performance · all time</h3>${products.map(x=>`<div class="row"><div><b>${html(x.name)}</b><p>${x.units} sold · ${x.onHand} on hand · ${money(x.weightedCost)} landed/unit</p></div><div><strong>${money(x.revenue)}</strong><p>${money(x.gross)} gross estimate</p></div></div>`).join('')}</div><div class="card"><h3>Outstanding balances · today</h3>${Object.entries(aging).map(([k,v])=>`<div class="row"><span>${k}</span><strong>${money(v)}</strong></div>`).join('')}</div></div><div class="card"><h3>12-Month Revenue Trend</h3>${trend.length?barRows(trend,x=>x.month,x=>x.revenue):'<p class="muted">No dated sales available.</p>'}</div>${accountantExports()}`}

