// Returns are dated reductions against an original sale, never synthetic payments.
function planSaleReturn(id,fields){
 const s=activeSale(id),qty=whole(fields.qty),remaining=saleQuantity(s),reason=requiredText(fields.reason,'Reason');
 knownProduct(s.productId);
 if(qty>remaining)throw Error('Return quantity exceeds the '+remaining+' unit(s) remaining on this invoice.');
 if(!['returned-resellable','never-delivered'].includes(fields.stock))throw Error('Confirm that the selected units are resellable or were never delivered.');
 if(String(fields.amount??'').trim()===''||!/^\d+(?:\.\d{1,2})?$/.test(String(fields.amount)))throw Error('Enter the invoice reduction with no more than two decimal places.');
 const amount=nonnegative(fields.amount),total=saleTotal(s),date=paymentDate(requiredText(fields.date,'Return date'));
 if(s.date&&date<s.date)throw Error('The return date cannot be before the invoice date.');
 if(cents(amount)>cents(total))throw Error('The reduction exceeds the remaining invoice total.');
 if(qty===remaining&&cents(amount)!==cents(total))throw Error('Returning all remaining units must remove the full remaining invoice total.');
 const paid=sumMoney(db.payments.filter(p=>!p.voided&&p.saleId===id)),after=(cents(total)-cents(amount)-cents(paid))/100;
 return {qty,amount,date,reason,stock:fields.stock,remaining:remaining-qty,newTotal:(cents(total)-cents(amount))/100,balance:Math.max(0,after),credit:Math.max(0,-after),creditAdded:Math.max(0,-after)-Math.max(0,paid-total)};
}
function recordSaleReturn(id,fields){
 const plan=planSaleReturn(id,fields),s=activeSale(id);
 confirmReturnCredit(plan,fields);
 const entry={id:uid('RETURN'),qty:plan.qty,amount:plan.amount,date:plan.date,reason:plan.reason,stock:plan.stock,createdAt:new Date().toISOString()};
 (s.returns??=[]).push(entry);return entry;
}
function returnSummaryHTML(s){if(!(s.returns||[]).length)return '';return `<section><p>Original total ${money(originalSaleTotal(s))} · Returned ${returnedQty(s)} · Kept ${saleQuantity(s)}</p>${saleReturns(s).map(r=>`<p>Return ${html(r.date)}: ${html(r.qty)} unit(s) · −${money(r.amount)}</p>`).join('')}</section>`;}
function openSaleReturn(id){
 const s=activeSale(id);if(saleQuantity(s)<=0)return openReturnHistory(id);
 const body=`<p><strong>${html(s.customer)}</strong><br>${html(id)}<br>${html(pname(s.productId))} · ${saleQuantity(s)} unit(s) available to return</p>${field('Quantity to return','qty','number',1)}${field('Invoice reduction','amount','number','')}${select('Stock condition','stock',[['','Choose stock condition'],['returned-resellable','Resellable return'],['never-delivered','Never delivered']])}${field('Return date','date','date',today())}${field('Reason','reason')}<p>Use the agreed return amount. Payments stay unchanged; no refund is sent.</p><div data-return-preview role="status"></div>${select('If this creates customer credit','creditChoice',[['','Choose if applicable'],['hold','Hold credit for this customer']])}<p>Only the selected quantity goes back into available stock. Damaged or missing stock needs separate review.</p>`;
 const dialog=openEditor('Return items',body,f=>{confirmReturnCredit(planSaleReturn(id,f),f);return commitFinancial('Items returned',()=>recordSaleReturn(id,f));},{},'Confirm return');
 dialog.classList.add('return-dialog');for(const name of ['qty','amount','stock','date'])dialog.querySelector('[name='+name+']').closest('label').classList.add('return-pair');
 const creditField=dialog.querySelector('[name=creditChoice]').closest('label');creditField.hidden=true;
 const preview=()=>{const f=Object.fromEntries(new FormData(dialog.querySelector('form'))),out=dialog.querySelector('[data-return-preview]');try{const p=planSaleReturn(id,{...f,reason:f.reason||'Preview'});creditField.hidden=p.creditAdded<=0;if(creditField.hidden)dialog.querySelector('[name=creditChoice]').value='';out.innerHTML=`<p>After return: <strong>${money(p.newTotal)} invoice total</strong><br>Balance due: <strong>${money(p.balance)}</strong><br>Customer credit on this invoice: <strong>${money(p.credit)}</strong><br>Inventory restored: <strong>${p.qty} unit(s)</strong></p>`;}catch(e){out.textContent=e.message;}};
 dialog.querySelector('form').addEventListener('input',preview);dialog.querySelector('form').addEventListener('change',preview);
}
function reverseSaleReturn(id,returnId,reason){
 const s=activeSale(id),r=(s.returns||[]).find(x=>x.id===returnId&&!x.voided);reason=requiredText(reason,'Reason');if(!r)throw Error('This return is missing or already reversed.');
 const shortfall=spentCreditShortfall(id);r.voided=true;
 if(spentCreditShortfall(id)>shortfall){delete r.voided;throw Error('Credit from this return has been used or refunded. Reverse the affected credit movements before reversing the return.');}
 Object.assign(r,{voidReason:reason,voidedAt:new Date().toISOString()});
}
function confirmReverseReturn(id,returnId){const s=activeSale(id),r=(s.returns||[]).find(x=>x.id===returnId&&!x.voided);if(!r)return;openEditor('Reverse incorrect return',`<p>This adds ${money(r.amount)} back to the invoice and deducts ${r.qty} unit(s) from available stock. Payments stay unchanged.</p>${field('Reason','reason')}`,f=>{const reason=requiredText(f.reason,'Reason');return commitFinancial('Return reversed',()=>reverseSaleReturn(id,returnId,reason));},{},'Reverse return');}
function actionButton(label,code){return `<button type="button" onclick="this.closest('dialog')?.close();${code}">${html(label)}</button>`;}
function openRecordDialog(title,body){const d=document.createElement('dialog');d.innerHTML=`<h2>${html(title)}</h2>${body}<div class="actions dialog-actions"><button type="button" data-close>Close</button></div>`;d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove());document.body.appendChild(d);d.showModal();return d;}
function openReturnHistory(id){const s=db.sales.find(x=>x.id===id);if(!s)return;openRecordDialog('Return history',`<p>${html(s.customer)} · ${html(id)}</p>${(s.returns||[]).map(r=>`<section><p>${html(r.date)} · ${html(r.qty)} unit(s) · ${money(r.amount)} ${r.voided?'· Reversed':''}</p><p>${html(r.reason)}</p>${!s.voided&&!r.voided?actionButton('Reverse incorrect return',`confirmReverseReturn(${actionArg(id)},${actionArg(r.id)})`):''}</section>`).join('')||'<p>No item returns recorded.</p>'}`);}
function invoiceActions(s){if(s.voided)return '<span class="tag">Voided</span>'+actionButton('View payments',`openInvoicePayments(${actionArg(s.id)})`);const x=invoiceRows().find(x=>x.id===s.id);return `<div class="actions">${actionButton('Invoice / PDF',`createInvoice(${actionArg(s.id)})`)}${actionButton('Edit invoice',`editSale(${actionArg(s.id)})`)}${actionButton('Record payment',`pay(${actionArg(s.id)})`)}${saleQuantity(s)>0?actionButton('Return items',`openSaleReturn(${actionArg(s.id)})`):''}${actionButton('View payments',`openInvoicePayments(${actionArg(s.id)})`)}${(s.returns||[]).length?actionButton('Return history',`openReturnHistory(${actionArg(s.id)})`):''}${x.balance<0?actionButton('Manage credit',`manageCredit(${actionArg(s.customer)})`):''}${actionButton('Customer',`openCustomer(${actionArg(s.customer)})`)}</div>`;}
function paymentActions(p){const activeInvoice=db.sales.some(s=>s.id===p.saleId&&!s.voided);return `<div class="actions">${activeInvoice&&!p.voided&&!isTransfer(p)?actionButton('Edit payment',`editPayment(${actionArg(p.id)})`):''}${actionButton('Receipt',`createReceipt(${actionArg(p.id)})`)}${activeInvoice&&!p.voided?actionButton(isTransfer(p)?'Reverse credit transfer':'Void payment',`voidPayment(${actionArg(p.id)})`):p.voided?'<span class="tag">Voided</span>':''}</div>`;}
function openInvoicePayments(id){const s=db.sales.find(x=>x.id===id);if(!s)return;const rows=db.payments.filter(p=>p.saleId===id);openRecordDialog('Invoice payments',`<p>${html(s.customer)} · ${html(id)}</p>${rows.map(p=>`<section><p><b>${money(p.amount)}</b> · ${html(p.date||'Date not recorded')} · ${html(p.method||'Method not recorded')}</p><p>${html(p.reference||'')}</p>${paymentActions(p)}</section>`).join('')||'<p>No payments recorded.</p>'}`);}
function universalSearch(){
 const q=globalQuery.trim().toLowerCase();if(!q)return '';const rows=[],match=values=>values.join(' ').toLowerCase().includes(q);
 for(const s of db.sales)if(match([s.id,s.customer,pname(s.productId),s.date,originalSaleTotal(s),saleTotal(s)])){const x=invoiceRows().find(x=>x.id===s.id);rows.push({type:'Invoice',id:s.id,title:s.id+' · '+s.customer,detail:pname(s.productId)+' · '+(s.date||'Date not recorded')+' · '+(s.voided?'Voided':money(Math.max(0,x.balance))+' due · '+money(Math.max(0,-x.balance))+' credit'),actions:invoiceActions(s)});}
 for(const p of db.payments){const s=db.sales.find(s=>s.id===p.saleId);if(match([p.id,p.saleId,s?.customer,p.amount,p.date,p.method,p.reference]))rows.push({type:'Payment',id:p.id,title:(s?.customer||'Unlinked payment')+' · '+money(p.amount),detail:p.saleId+' · '+(p.date||'Date not recorded')+' · '+(p.method||'Method not recorded'),actions:paymentActions(p)});}
 for(const o of db.orders)if(match([o.id,o.maker,o.status,o.supplierReference,...(o.lines||[]).map(l=>pname(l.productId))]))rows.push({type:'PO',id:o.id,title:o.id+' · '+o.maker,detail:o.cancelled?'Cancelled':o.status,actions:actionButton('Order details',`openPO(${actionArg(o.id)})`)+(o.cancelled?'':actionButton('Edit order',`editPO(${actionArg(o.id)})`)+(o.status!=='Received'?actionButton('Receive stock',`receivePO(${actionArg(o.id)})`):''))});
 for(const e of db.expenses)if(match([e.id,e.vendor,e.category,e.date,e.notes]))rows.push({type:'Expense',id:e.id,title:e.vendor,detail:money(e.amount)+' · '+e.category+(e.voided?' · Voided':''),actions:e.voided?'':actionButton('Edit expense',`editExpense(${actionArg(e.id)})`)});
 for(const c of db.claims)if(match([c.id,c.customer,pname(c.productId),c.status]))rows.push({type:'Warranty',id:c.id,title:c.customer+' · '+pname(c.productId),detail:c.voided?'Voided':c.status,actions:actionButton('Claim details',`openClaim(${actionArg(c.id)})`)+(c.voided?'':actionButton('Edit warranty',`editClaim(${actionArg(c.id)})`))});
 for(const p of products())if(match([p.name,p.maker]))rows.push({type:'Product',id:p.id,title:p.name,detail:p.maker+(p.archived?' · Archived':''),actions:actionButton('Edit product',`editProduct(${actionArg(p.id)})`)+actionButton('Inventory history',`openInventoryHistory(${actionArg(p.id)})`)});
 return `<div class="search-results card"><div class="row"><b>Search results (${rows.length})</b><button onclick="clearSearch()">Close</button></div>${empty(rows)}${rows.slice(0,30).map(x=>`<article class="search-record" data-search-id="${html(x.id)}"><span class="tag">${html(x.type)}</span><h3>${html(x.title)}</h3><p>${html(x.detail||'')}</p><div class="actions">${x.actions}</div></article>`).join('')}${rows.length>30?'<p>Showing 30 results. Add an invoice number, date, or more of the name to narrow your search.</p>':''}</div>`;
}
function confirmReturnCredit(plan,fields){if(plan.creditAdded>0&&fields.creditChoice!=='hold')throw Error('Choose Hold credit for this customer before confirming. No refund is sent.');}
function validateReturns(data){
 for(const s of data.sales||[]){if(s.returns===undefined)continue;if(!Array.isArray(s.returns))throw Error('Invoice return history needs review.');const ids=new Set();let qty=0,amount=0;
  for(const r of s.returns){if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||!Number.isSafeInteger(r.qty)||r.qty<=0||typeof r.amount!=='number'||r.amount<0||!Number.isFinite(r.amount)||Math.abs(r.amount*100-Math.round(r.amount*100))>0.00001||typeof r.reason!=='string'||!r.reason.trim()||!r.date||paymentDate(r.date)!==r.date||!['returned-resellable','never-delivered'].includes(r.stock)||r.voided!==undefined&&typeof r.voided!=='boolean')throw Error('Invoice return history needs review.');ids.add(r.id);if(!r.voided){qty+=r.qty;amount+=cents(r.amount);}}
  if(qty>Number(s.qty)||amount>cents(originalSaleTotal(s)))throw Error('Invoice returns exceed the original sale.');
 }
}
function exportReturns(){downloadCSV('returns',['Return ID','Invoice','Customer','Product','Return Date','Quantity','Invoice Reduction','Stock Condition','Reason','Reversed'],db.sales.flatMap(s=>(s.returns||[]).map(r=>[r.id,s.id,s.customer,pname(s.productId),r.date,r.qty,r.amount,r.stock,r.reason,!!r.voided])));}

// Purchase credit is linked to its warranty claims; old orders are never backfilled.
function makerKey(value){return String(value||'').trim().toLowerCase().replace(/\s+/g,' ');}
function claimMaker(claim){return claim.creditMaker||products().find(p=>p.id===claim.productId)?.maker||'';}
function availableMakerClaims(maker){return db.claims.filter(c=>!c.voided&&makerKey(claimMaker(c))===makerKey(maker)&&cents(c.approvedCredit||0)>cents(c.appliedCredit||0));}
function makerCredit(maker){return availableMakerClaims(maker).reduce((n,c)=>n+cents(c.approvedCredit||0)-cents(c.appliedCredit||0),0)/100;}
function creditAllocationPlan(maker,credit){let remaining=cents(credit);const allocations=[];for(const c of availableMakerClaims(maker)){const amount=Math.min(remaining,cents(c.approvedCredit||0)-cents(c.appliedCredit||0));if(amount>0){allocations.push({claimId:c.id,amount:amount/100});remaining-=amount;}}if(remaining)throw Error('The requested warranty credit exceeds the amount available for this manufacturer.');return allocations;}
function planPurchaseOrder(f,lines){
 const maker=requiredText(f.maker,'Manufacturer'),shipping=nonnegative(f.shipping),fees=nonnegative(f.fees),credit=nonnegative(f.credit),eta=optionalDate(f.eta);
 if(!lines.length)throw Error('Add at least one product line.');
 lines=lines.map(l=>{const p=knownProduct(l.productId);if(p.archived)throw Error('Choose an active product for a new purchase order.');if(makerKey(p.maker)!==makerKey(maker))throw Error('Each product must belong to this manufacturer. Use a separate order for another manufacturer.');return {productId:p.id,qty:whole(l.qty),unitCost:nonnegative(l.unitCost),received:0};});
 const order={maker,shipping,fees,credit,eta,purchaseDate:optionalDate(f.purchaseDate),supplierReference:String(f.supplierReference||'').trim(),lines};
 if(poTotal(order)<0)throw Error('Warranty credit cannot exceed the items, shipping and fees on this order.');
 order.creditAllocations=creditAllocationPlan(maker,credit);return order;
}
function purchaseOrderChanges(order,f){
 const changes={eta:optionalDate(f.eta),supplierReference:String(f.supplierReference||'').trim(),shipping:nonnegative(f.shipping),fees:nonnegative(f.fees)},lines=order.lines.map((l,i)=>({...l,qty:whole(f['qty'+i]),unitCost:nonnegative(f['cost'+i])}));
 if(lines.some(l=>l.qty<Number(l.received||0)))throw Error('Ordered quantity cannot be lower than quantity received.');
 if(poTotal({...order,...changes,lines})<0)throw Error('This change would make the order cost lower than its warranty credit. Review the credit before changing the cost.');
 return {...changes,lines};
}
function readPOLines(form){return [...form.querySelectorAll('.po-line')].map(x=>({productId:x.querySelector('[name=lineProduct]').value,qty:x.querySelector('[name=lineQty]').value,unitCost:x.querySelector('[name=lineCost]').value}));}
function updatePOPreview(){const form=document.getElementById('po'),out=document.getElementById('po-preview');if(!form||!out)return;const f=Object.fromEntries(new FormData(form)),available=makerCredit(f.maker);let body=`<p>Available warranty credit for ${html(f.maker||'this manufacturer')}: <strong>${money(available)}</strong></p>`;try{const p=planPurchaseOrder(f,readPOLines(form));body+=`<div class="order-breakdown"><span>Items before credit</span><strong>${money(poSubtotal(p))}</strong><span>Shipping & fees</span><strong>${money(p.shipping+p.fees)}</strong><span>Warranty credit</span><strong>−${money(p.credit)}</strong><span>Net order cost</span><strong>${money(poTotal(p))}</strong></div>${p.creditAllocations.length?`<details><summary>Credit comes from ${p.creditAllocations.length} claim(s)</summary>${p.creditAllocations.map(a=>`<p>${html(a.claimId)} · ${money(a.amount)}</p>`).join('')}</details>`:''}<p>Credit left after saving: <strong>${money((cents(available)-cents(p.credit))/100)}</strong>. Stock is added only when received.</p>`;}catch(e){body+=`<p class="editor-error">${html(e.message)}</p>`;}out.innerHTML=body;}
function checkOrderCancellation(o){
 if(!o||o.cancelled)throw Error('This order is missing or already cancelled.');
 if(o.lines.some(l=>Number(l.received||0)>0))throw Error('Stock has already been received. Review a supplier return before cancelling; received inventory will not be removed automatically.');
 if(cents(o.credit||0)>0&&!Array.isArray(o.creditAllocations))throw Error('This older order has no links to its original credit claims. Keep a backup and reconcile those claims before cancelling; the app will not guess which credit to restore.');
 if(cents(sumMoney(o.creditAllocations||[]))!==cents(o.credit||0))throw Error('This order’s credit links need review before cancellation.');
 const seen=new Set();for(const a of o.creditAllocations||[]){const c=db.claims.find(c=>c.id===a.claimId);if(seen.has(a.claimId)||!c||c.voided||cents(a.amount)<=0||cents(c.appliedCredit||0)<cents(a.amount))throw Error('A linked warranty credit needs review before cancellation.');seen.add(a.claimId);}
}
function cancelOrderRecord(id,reason){reason=requiredText(reason,'Reason');const o=db.orders.find(x=>x.id===id);checkOrderCancellation(o);for(const a of o.creditAllocations||[]){const c=db.claims.find(c=>c.id===a.claimId);c.appliedCredit=(cents(c.appliedCredit||0)-cents(a.amount))/100;}Object.assign(o,{cancelled:true,cancelReason:reason,status:'Cancelled',cancelledAt:new Date().toISOString(),...(Number(o.credit)>0?{creditReleasedAt:new Date().toISOString()}:{} )});}
function openPO(id){const o=db.orders.find(x=>x.id===id);if(!o)return;openRecordDialog('Purchase order details',`<p><strong>${html(o.id)} · ${html(o.maker)}</strong><br>${html(o.cancelled?'Cancelled':o.status)}${o.supplierReference?' · '+html(o.supplierReference):''}</p>${o.lines.map(l=>`<p>${html(pname(l.productId))} · ${html(l.qty)} ordered · ${html(Number(l.received||0))} received<br>${money(l.unitCost)} each before credit</p>`).join('')}<div class="order-preview"><p>Items ${money(poSubtotal(o))}<br>Shipping & fees ${money(Number(o.shipping||0)+Number(o.fees||0))}<br>Warranty credit ${money(o.credit||0)}<br><strong>Net order cost ${money(poTotal(o))}</strong></p><p>This is the order cost. Supplier payments are not tracked here.</p></div><p>Purchase date: ${html(o.purchaseDate||o.date||'Not recorded')}</p><h3>Warranty credit used</h3>${(o.creditAllocations||[]).map(a=>`<p>${html(a.claimId)} · ${money(a.amount)}${o.creditReleasedAt?' · Released on cancellation':''} ${actionButton('View claim',`openClaim(${actionArg(a.claimId)})`)}</p>`).join('')||(Number(o.credit)>0?'<p>Older order: the total credit was saved without links to individual claims. No links have been guessed.</p>':'<p>No warranty credit used.</p>')}<h3>Stock receipts</h3>${(o.receipts||[]).map(r=>`<p>${html(r.date)} · ${r.lines.map(l=>html(pname(l.productId))+' × '+l.qty).join('; ')}</p>`).join('')||'<p>Earlier receipt dates were not recorded.</p>'}<div class="actions">${[...new Set(o.lines.map(l=>l.productId))].map(pid=>actionButton(pname(pid)+' history',`openInventoryHistory(${actionArg(pid)})`)).join('')}</div>${attachmentsView('purchase-order',id)}${o.cancelled?`<p>Cancellation reason: ${html(o.cancelReason||'Not recorded')}</p>`:`<div class="actions">${actionButton('Edit order',`editPO(${actionArg(id)})`)}${actionButton('Correct purchase date',`editRecordDate('order',${actionArg(id)})`)}${o.status!=='Received'?actionButton('Receive stock',`receivePO(${actionArg(id)})`):''}${actionButton('Cancel order',`cancelPO(${actionArg(id)})`)}</div>`}`);}
function openClaim(id){const c=db.claims.find(x=>x.id===id);if(!c)return;const orders=db.orders.filter(o=>(o.creditAllocations||[]).some(a=>a.claimId===id)),sale=db.sales.find(s=>s.id===c.relatedSaleId);openRecordDialog('Warranty claim details',`<p><strong>${html(c.customer)} · ${html(c.id)}</strong><br>${html(pname(c.productId))} · ${html(c.voided?'Voided':c.status)}</p><p>Claim date: ${html(c.date||'Not recorded')}<br>Manufacturer: ${html(claimMaker(c))}<br>Replacement stock deducted: ${!c.voided?replacementStockQty(c):0} unit(s)</p><div class="order-preview"><p>Approved credit ${money(c.approvedCredit||0)}<br>Used credit ${money(c.appliedCredit||0)}<br><strong>Available credit ${money(c.voided?0:Math.max(0,Number(c.approvedCredit||0)-Number(c.appliedCredit||0)))}</strong></p></div>${replacementHistoryHTML(c)}<h3>Linked purchase orders</h3>${orders.map(o=>`<p>${html(o.id)} · ${money(sumMoney(o.creditAllocations.filter(a=>a.claimId===id)))}${o.creditReleasedAt?' · Released on cancellation':''} ${actionButton('View order',`openPO(${actionArg(o.id)})`)}</p>`).join('')||'<p>No linked orders. Older used credits may not have order links.</p>'}${attachmentsView('warranty',id)}<div class="actions">${!c.voided?actionButton('Edit warranty',`editClaim(${actionArg(id)})`)+actionButton('Correct claim date',`editRecordDate('claim',${actionArg(id)})`):''}${sale&&!sale.voided?actionButton('Related invoice / PDF',`createInvoice(${actionArg(sale.id)})`):''}${actionButton('Customer',`openCustomer(${actionArg(c.customer)})`)}${!c.voided?actionButton('Use warranty credit',`openPurchaseForMaker(${actionArg(claimMaker(c))})`):''}</div>`);}
function openPurchaseForMaker(maker){go('Purchase Orders');const form=document.getElementById('po');if(!form)return;const current=form.elements.maker.value;if(makerKey(current)!==makerKey(maker)&&!confirm('Switch this purchase-order draft to '+maker+'? Product lines and entered amounts stay in place for your review.'))return;form.elements.maker.value=maker;updatePOPreview();form.scrollIntoView({block:'start'});}
function validateCreditAllocations(data){
 const totals=new Map();for(const o of data.orders||[]){if(o.creditAllocations===undefined)continue;if(!Array.isArray(o.creditAllocations))throw Error('Purchase-order credit links need review.');const seen=new Set();let sum=0;for(const a of o.creditAllocations){if(!a||typeof a.claimId!=='string'||!a.claimId||seen.has(a.claimId)||typeof a.amount!=='number'||a.amount<=0||!Number.isFinite(a.amount)||Math.abs(a.amount*100-Math.round(a.amount*100))>0.00001)throw Error('Purchase-order credit links need review.');seen.add(a.claimId);sum+=cents(a.amount);if(!o.cancelled)totals.set(a.claimId,(totals.get(a.claimId)||0)+cents(a.amount));}if(sum!==cents(o.credit||0)||o.creditReleasedAt&&!o.cancelled||o.cancelled&&sum>0&&!o.creditReleasedAt)throw Error('Purchase-order credit totals need review.');}
 for(const [id,amount] of totals){const c=(data.claims||[]).find(c=>c.id===id);if(!c||c.voided||cents(c.appliedCredit||0)<amount||cents(c.approvedCredit||0)<cents(c.appliedCredit||0))throw Error('A linked warranty claim needs review.');}
}

// Operational history is derived from existing records. Undated history stays undated.
function replacementEvents(c){return (c.replacementEvents||[]).filter(r=>!r.voided);}
function replacementQty(c){return (c.replacementSent?Number(c.qty||0):0)+replacementEvents(c).reduce((n,r)=>n+r.qty,0);}
function replacementStockQty(c){return (c.replacementSent?Number(c.qty||0):0)+replacementEvents(c).filter(r=>r.source==='inventory').reduce((n,r)=>n+r.qty,0);}
function inventory(){return products().map(p=>{const received=db.orders.filter(o=>!o.cancelled).flatMap(o=>o.lines||[]).filter(l=>l.productId===p.id).reduce((n,l)=>n+Number(l.received||0),0),sold=db.sales.filter(s=>!s.voided&&s.productId===p.id).reduce((n,s)=>n+saleQuantity(s),0),war=db.claims.filter(c=>!c.voided&&c.productId===p.id).reduce((n,c)=>n+replacementStockQty(c),0),adj=db.adjustments.filter(a=>!a.voided&&a.productId===p.id).reduce((n,a)=>n+Number(a.qty||0),0);return {...p,onHand:received-sold-war+adj,received,sold,war};});}
function inventoryMovements(productId){
 const rows=[],add=(productId,type,id,date,label,qty,inactive=false,detail='')=>rows.push({productId,type,id,date:date||'',label,qty:inactive?0:qty,recordedQty:qty,inactive,detail});
 for(const o of db.orders){
  for(const r of o.receipts||[])for(const l of r.lines)add(l.productId,'order',o.id,r.date,'Purchase received',l.qty,!!o.cancelled,r.id);
  (o.lines||[]).forEach((l,i)=>{const tracked=(o.receipts||[]).flatMap(r=>r.lines).filter(x=>x.lineIndex===i).reduce((n,x)=>n+x.qty,0),remaining=Number(l.received||0)-tracked;if(remaining)add(l.productId,'order',o.id,'','Earlier purchase receipts',remaining,!!o.cancelled,'Receipt date not recorded');});
 }
 for(const s of db.sales){add(s.productId,'sale',s.id,s.date,'Sale',-Number(s.qty||0),!!s.voided,s.customer||'');for(const r of s.returns||[])add(s.productId,'sale',s.id,r.date,'Customer return',r.qty,!!(s.voided||r.voided),r.id+' · '+r.reason);}
 for(const c of db.claims){if(c.replacementSent)add(c.productId,'claim',c.id,'','Earlier replacement sent',-Number(c.qty||0),!!c.voided,'Sent date not recorded');for(const r of c.replacementEvents||[])add(c.productId,'claim',c.id,r.date,r.source==='inventory'?'Replacement sent':'Supplier-direct replacement',r.source==='inventory'?-r.qty:0,!!(c.voided||r.voided),r.id+' · '+r.qty+' unit(s)'+(r.source==='supplier-direct'?' · No local stock used':''));}
 for(const a of db.adjustments)add(a.productId,'adjustment',a.id,a.date,a.type||a.reason||'Stock adjustment',Number(a.qty||0),!!a.voided,a.notes||'');
 return rows.filter(r=>!productId||r.productId===productId).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||String(a.id).localeCompare(String(b.id)));
}
function openInventoryHistory(productId=''){
 const p=inventory().find(p=>p.id===productId),rows=inventoryMovements(productId),effect=rows.reduce((n,r)=>n+r.qty,0);
 openRecordDialog('Inventory history',`<p><strong>${html(p?.name||'All products')}</strong> · ${p?p.onHand:inventory().reduce((n,p)=>n+p.onHand,0)} on hand</p><p>Stock changes shown: ${effect>0?'+':''}${effect}. Earlier receipts and replacements may have no recorded date. Reversed or voided entries have no current stock effect.</p><div class="actions">${actionButton('Export history CSV',`exportInventoryHistory(${actionArg(productId)})`)}</div>${rows.map(r=>`<section class="movement-row"><div><strong>${html(r.label)}</strong><span class="tag">${r.qty>0?'+':''}${r.qty} stock</span></div><p>${html(r.date||'Date not recorded')} · ${html(r.id)}${!p?' · '+html(pname(r.productId)):''}${r.inactive?' · Reversed / voided':''}</p><p>${html(r.detail)}</p>${actionButton('Open record',`openSource(${actionArg(r.type)},${actionArg(r.id)})`)}</section>`).join('')||'<p>No stock movements recorded.</p>'}`);
}
function exportInventoryHistory(productId=''){downloadCSV('inventory-history',['Product','Date','Movement','Record','Stock Effect','Originally Recorded Effect','Inactive','Details'],inventoryMovements(productId).map(r=>[pname(r.productId),r.date,r.label,r.id,r.qty,r.recordedQty,r.inactive,r.detail]));}
function openSource(type,id){
 if(type==='order')return openPO(id);if(type==='claim')return openClaim(id);if(type==='product')return openInventoryHistory(id);if(type==='adjustment')return openAdjustment(id);
 if(type==='sale'){const s=db.sales.find(x=>x.id===id);if(!s)return alert('This invoice could not be found.');return openRecordDialog('Invoice details',`<p><strong>${html(s.id)} · ${html(s.customer)}</strong></p><p>${html(pname(s.productId))} · ${html(s.qty)} originally sold · ${money(saleTotal(s))} after returns</p><p>Date: ${html(s.date||'Not recorded')}</p>${invoiceActions(s)}${!s.voided?actionButton('Correct invoice date',`editRecordDate('sale',${actionArg(id)})`):''}`);}
 if(type==='payment'){const p=db.payments.find(x=>x.id===id);if(!p)return alert('This payment could not be found.');return openRecordDialog('Payment details',`<p><strong>${html(p.id)}</strong> · ${money(p.amount)}</p><p>Invoice: ${html(p.saleId||'Not linked')}<br>${html(p.date||'Date not recorded')} · ${html(p.method||'Method not recorded')}</p><p>${html(p.reference||'')} ${html(p.notes||'')}</p>${paymentActions(p)}${!db.sales.some(s=>s.id===p.saleId)?'<p>This invoice link needs correction. Keep the payment and a backup; confirm the original invoice before changing the link.</p>':actionButton('Open invoice',`openSource('sale',${actionArg(p.saleId)})`)}`);}
}
function receiveOrder(id,quantities,date){
 const o=db.orders.find(x=>x.id===id);if(!o||o.cancelled)throw Error('Order is missing or cancelled.');date=paymentDate(requiredText(date,'Date stock arrived'));
 if(quantities.length!==o.lines.length)throw Error('Review the order lines.');quantities=quantities.map(n=>whole(n,'Received quantity',0));if(!quantities.some(Boolean))throw Error('Enter a quantity to receive.');if(quantities.some((n,i)=>n>Number(o.lines[i].qty)-Number(o.lines[i].received||0)))throw Error('Received quantity exceeds the remaining order.');
 const receipt={id:uid('REC'),date,createdAt:new Date().toISOString(),lines:quantities.flatMap((qty,lineIndex)=>qty?[{lineIndex,productId:o.lines[lineIndex].productId,qty}]:[])};
 quantities.forEach((n,i)=>o.lines[i].received=Number(o.lines[i].received||0)+n);(o.receipts||=[]).push(receipt);o.status=o.lines.every(l=>l.received>=l.qty)?'Received':'Partially Received';return receipt;
}
function receivePO(id){const o=db.orders.find(x=>x.id===id);if(!o||o.cancelled)return;openEditor('Receive purchase order',field('Date stock arrived','receivedDate','date',today())+o.lines.map((l,i)=>field(pname(l.productId)+' — remaining '+(l.qty-(l.received||0)),'receive'+i,'number',0)).join(''),f=>commitFinancial('Inventory received',()=>receiveOrder(id,o.lines.map((l,i)=>f['receive'+i]),f.receivedDate)));}

// Each cost is either counted here or linked to a saved expense, never both.
function costEntry(amount,date,expenseId='',note=''){return {amount:nonnegative(amount),date:optionalDate(date),expenseId:String(expenseId||''),note:String(note||'')};}
function operatingCostRows(data=db){
 const rows=[],add=(entry,kind,type,id,key)=>{if(entry)rows.push({...entry,kind,type,id,key});};
 for(const c of data.claims||[])if(!c.voided){if(c.costReview){add(c.costReview.product,'Warranty products','claim',c.id,c.id+':legacy:product');add(c.costReview.shipping,'Warranty shipping','claim',c.id,c.id+':legacy:shipping');}for(const r of c.replacementEvents||[])if(!r.voided){add(r.productCost,'Warranty products','claim',c.id,r.id+':product');add(r.shippingCost,'Warranty shipping','claim',c.id,r.id+':shipping');}}
 for(const a of data.adjustments||[])if(!a.voided&&Number(a.qty)<0)add(a.costReview,'Inventory losses / non-sale use','adjustment',a.id,a.id+':loss');return rows;
}
function costReportDate(row,data=db){return row.expenseId?((data.expenses||[]).find(e=>e.id===row.expenseId)?.date||''):row.date;}
function pendingCostReviews(data=db){return [...(data.claims||[]).filter(c=>!c.voided&&!c.costReview&&!c.operationsVersion&&(c.replacementSent||Number(c.replacementCost)>0||Number(c.shipping)>0)).map(c=>({type:'claim',id:c.id,title:'Review earlier warranty costs',detail:c.customer+' · '+pname(c.productId)})),...(data.adjustments||[]).filter(a=>!a.voided&&Number(a.qty)<0&&!a.costReview).map(a=>({type:'adjustment',id:a.id,title:'Review stock deduction cost',detail:pname(a.productId)+' · '+(a.type||a.reason||'Adjustment')}))];}
function validateCostLinks(data){const totals=new Map();for(const r of operatingCostRows(data)){if(r.expenseId)totals.set(r.expenseId,(totals.get(r.expenseId)||0)+cents(r.amount));}for(const [id,amount] of totals){const e=(data.expenses||[]).find(e=>e.id===id);if(!e||e.voided||cents(e.amount)<amount)throw Error('An expense linked to warranty or inventory costs is missing, voided or smaller than its linked costs. Review those cost links first.');}}
function expenseCostField(label,name){return select(label,name,[['','Count this cost here'],...db.expenses.filter(e=>!e.voided).map(e=>[e.id,e.id+' · '+e.vendor+' · '+money(e.amount)])]);}
function planReplacement(id,f){
 const c=db.claims.find(c=>c.id===id);if(!c||c.voided)throw Error('Claim is missing or voided.');const qty=whole(f.qty,'Replacement quantity');if(qty>Number(c.qty)-replacementQty(c))throw Error('Replacement quantity exceeds the units still awaiting replacement.');if(!['inventory','supplier-direct'].includes(f.source))throw Error('Choose where the replacement came from.');const date=paymentDate(requiredText(f.date,'Date sent')),unitCost=nonnegative(f.unitCost),shipping=nonnegative(f.shipping);
 return {id:uid('SEND'),date,qty,source:f.source,unitCost,productCost:costEntry(cents(qty*unitCost)/100,date,f.productExpenseId),shippingCost:costEntry(shipping,date,f.shippingExpenseId),notes:requiredText(f.notes,'Replacement note'),createdAt:new Date().toISOString()};
}
function recordReplacement(id,f){const r=planReplacement(id,f),c=db.claims.find(c=>c.id===id);const candidate=structuredClone(db);(candidate.claims.find(c=>c.id===id).replacementEvents||=[]).push(r);validateOperations(candidate);(c.replacementEvents||=[]).push(r);return r;}
function openReplacement(id){
 const c=db.claims.find(c=>c.id===id);if(!c||c.voided)return;const remaining=Number(c.qty)-replacementQty(c);if(remaining<=0)return alert('All units already have a replacement recorded.');
 const d=openEditor('Record replacement sent',`<p>${html(c.customer)} · ${html(pname(c.productId))}. ${remaining} unit(s) still awaiting replacement. Manufacturer approval is unchanged.</p>`+field('Quantity','qty','number',remaining)+field('Date sent','date','date',today())+select('Replacement supplied from','source',[['inventory','My inventory'],['supplier-direct','Supplier shipped directly']])+field('Product cost per unit','unitCost','number',cents(weightedCosts()[c.productId]||0)/100)+field('Shipping paid by this business','shipping','number',0)+expenseCostField('Product cost treatment','productExpenseId')+expenseCostField('Shipping cost treatment','shippingExpenseId')+field('Replacement note','notes')+'<p class="muted">Confirm the actual or estimated product cost. Link an existing expense if it already includes this cost.</p><div class="order-preview" data-replacement-preview role="status"></div>',f=>{planReplacement(id,f);return commitFinancial('Replacement sent',()=>recordReplacement(id,f));},{},'Record replacement');
 const update=()=>{try{const f=Object.fromEntries(new FormData(d.querySelector('form'))),qty=whole(f.qty),cost=cents(qty*nonnegative(f.unitCost))/100+nonnegative(f.shipping);d.querySelector('[data-replacement-preview]').textContent=(f.source==='inventory'?qty+' unit(s) will leave inventory.':'No local stock will change.')+' Recorded cost '+money(cost)+'. Linked expenses are counted only in Expenses.';}catch{d.querySelector('[data-replacement-preview]').textContent='Enter a valid quantity and cost to preview.';}};
 d.classList.add('replacement-dialog');for(const name of ['qty','date','unitCost','shipping'])d.querySelector('[name='+name+']').closest('label').classList.add('replacement-pair');
 d.querySelector('[name=source]').addEventListener('change',e=>{d.querySelector('[name=unitCost]').value=e.target.value==='supplier-direct'?0:cents(weightedCosts()[c.productId]||0)/100;update();});d.addEventListener('input',update);d.addEventListener('change',update);update();
}
function reverseReplacement(id,eventId,reason){const c=db.claims.find(c=>c.id===id),r=c?.replacementEvents?.find(r=>r.id===eventId);if(!r||r.voided||c.voided)throw Error('This replacement is missing or already reversed.');Object.assign(r,{voided:true,voidReason:requiredText(reason,'Reason'),voidedAt:new Date().toISOString()});}
function confirmReverseReplacement(id,eventId){openEditor('Reverse an incorrect replacement entry',`<p>Use only to correct an entry made by mistake. This removes its cost from the estimate and restores stock if this entry deducted it. It does not record a physical return or change manufacturer approval.</p>${field('Reason','reason')}`,f=>commitFinancial('Replacement entry reversed',()=>reverseReplacement(id,eventId,f.reason)),{},'Reverse incorrect entry');}
function reviewClaimCosts(id){const c=db.claims.find(c=>c.id===id);if(!c||c.voided)return;const old=c.costReview;openEditor('Review earlier warranty costs',`<p>${html(c.id)} · ${html(c.customer)}</p><p>Confirm the total product cost and shipping actually incurred before replacement tracking was added. Original entries show product cost ${money(c.replacementCost||0)} and shipping ${money(c.shipping||0)}; confirm whether those totals are correct. This does not send a replacement or change stock.</p>`+field('Total earlier product cost','productAmount','number',old?.product.amount??'')+expenseCostField('Product cost treatment','productExpenseId')+field('Total earlier shipping cost','shippingAmount','number',old?.shipping.amount??'')+expenseCostField('Shipping cost treatment','shippingExpenseId')+field('Cost date (blank if unknown)','date','date',old?.product.date||'')+field('Explanation / verification','note')+'<p>If no cost was incurred, enter zero and explain. If another recorded movement already includes the cost, confirm that entry and explain before entering zero here.</p>',f=>{if(f.productAmount===''||f.shippingAmount==='')throw Error('Confirm both amounts, using zero when no additional cost was incurred.');const note=requiredText(f.note,'Explanation'),review={product:costEntry(f.productAmount,f.date,f.productExpenseId,note),shipping:costEntry(f.shippingAmount,f.date,f.shippingExpenseId,note),reviewedAt:new Date().toISOString()};return commitFinancial('Earlier warranty costs reviewed',()=>c.costReview=review);},{productExpenseId:old?.product.expenseId||'',shippingExpenseId:old?.shipping.expenseId||'',note:old?.product.note||''});}
function replacementHistoryHTML(c){return `<h3>Replacements sent</h3><p>${replacementQty(c)} of ${html(c.qty)} unit(s) recorded · ${replacementStockQty(c)} from inventory</p>${c.replacementSent?'<p>Earlier replacement: '+html(c.qty)+' unit(s) from inventory. Sent date was not recorded; the original stock deduction is retained.</p>':''}${(c.replacementEvents||[]).map(r=>`<section class="movement-row"><p><strong>${html(r.date)} · ${r.qty} unit(s)</strong> · ${r.source==='inventory'?'My inventory':'Supplier-direct'}${r.voided?' · Reversed':''}</p><p>${html(r.notes)} · Product cost ${money(r.productCost.amount)} · Shipping ${money(r.shippingCost.amount)}</p>${r.voided?'<p>'+html(r.voidReason)+'</p>':!c.voided?actionButton('Reverse incorrect entry',`confirmReverseReplacement(${actionArg(c.id)},${actionArg(r.id)})`):''}</section>`).join('')}${!c.voided&&replacementQty(c)<Number(c.qty)?actionButton('Record replacement sent',`openReplacement(${actionArg(c.id)})`):''}${!c.voided&&!c.operationsVersion&&(c.costReview||c.replacementSent||Number(c.replacementCost)>0||Number(c.shipping)>0)?actionButton(c.costReview?'Review saved earlier costs':'Review earlier costs',`reviewClaimCosts(${actionArg(c.id)})`):''}${actionButton('Inventory history',`openInventoryHistory(${actionArg(c.productId)})`)}`;}
function approvalOptions(c){return WARRANTY_STATUSES.filter(s=>s!=='Replacement Sent').map(s=>[s,s]).concat(c?.status==='Replacement Sent'?[['Replacement Sent','Replacement Sent (earlier status; choose approval separately)']]:[]);}
function warrantyView(){return `<div class="card"><h3>Warranty claim</h3><p>Track manufacturer approval here. Use Record replacement sent in claim details when a replacement leaves inventory or the supplier ships it directly.</p><form id="claim"><div class="fields">${customerField()}${select('Product','productId',products().map(p=>[p.id,p.name]))}${field('Quantity','qty','number',1)}${field('Approved credit','approvedCredit','number',0)}${field('Claim date','date','date',today())}${select('Manufacturer approval','status',approvalOptions())}${select('Related Sale','relatedSaleId',[['','None'],...db.sales.filter(s=>!s.voided).map(s=>[s.id,s.customer+' · '+s.id+' · '+pname(s.productId)])])}</div><button class="primary">Save Claim</button></form></div><div class="card">${empty(db.claims)}${db.claims.map(c=>`<article class="row"><div><b>${html(c.customer)} · ${html(pname(c.productId))}</b><p>Approval: ${html(c.voided?'Voided':c.status)} · Replacements recorded: ${replacementQty(c)} / ${html(c.qty)}</p></div><div class="actions"><strong>${money(Math.max(0,Number(c.approvedCredit||0)-Number(c.appliedCredit||0)))} available</strong>${actionButton('Claim details',`openClaim(${actionArg(c.id)})`)}${!c.voided?`<details><summary>More actions</summary>${actionButton('Void claim',`voidClaim(${actionArg(c.id)})`)}</details>`:''}</div></article>`).join('')}</div>`;}
function editClaim(id){const c=db.claims.find(c=>c.id===id);if(!c||c.voided)return;openEditor('Edit warranty claim',customerField()+field('Approved credit','approvedCredit','number')+select('Manufacturer approval','status',approvalOptions(c))+field('Related invoice ID','relatedSaleId')+'<p>Approval changes do not send replacements or change inventory. Record replacement shipments separately in claim details.</p>',f=>{const change={customer:requiredText(f.customer,'Customer'),approvedCredit:nonnegative(f.approvedCredit),status:f.status,relatedSaleId:f.relatedSaleId};if(change.approvedCredit<Number(c.appliedCredit||0))throw Error('Approved credit cannot be less than credit already applied.');if(f.relatedSaleId&&!db.sales.some(s=>s.id===f.relatedSaleId&&normName(s.customer)===normName(f.customer)))throw Error('Select an invoice belonging to this customer.');if(!approvalOptions(c).some(([v])=>v===f.status))throw Error('Choose a manufacturer approval status.');return commitFinancial('Warranty updated',()=>Object.assign(c,change));},c);}
function voidClaim(id){const c=db.claims.find(c=>c.id===id);if(!c||c.voided)return;if(Number(c.appliedCredit)>0)return alert('This claim has manufacturer credit applied to a purchase order. Review that allocation before voiding.');if(replacementQty(c)>0||c.costReview)return alert('This claim has a replacement or reviewed cost history. Keep it and use Closed for the approval status. Reverse an incorrect new replacement entry separately; voiding must not restore stock or erase costs.');reasonDialog('Void warranty claim',why=>commitFinancial('Warranty claim voided',()=>Object.assign(c,{voided:true,voidReason:why})));}
function recordAdjustment(f){knownProduct(f.productId);const qty=whole(f.qty,'Quantity',-1000000);if(!qty)throw Error('Quantity cannot be zero.');if(f.reason==='Warranty Replacement')throw Error('Record a replacement from its warranty claim so stock is deducted only once.');const note=requiredText(f.notes,'Justification'),date=paymentDate(requiredText(f.date,'Date')),a={id:uid('ADJ'),productId:f.productId,qty,type:f.reason,reason:requiredText(f.reason,'Reason'),notes:note,date};if(qty<0){if(f.costAmount==='')throw Error('Confirm the total cost of this stock deduction.');a.costReview=costEntry(f.costAmount,date,f.expenseId,note);}const candidate=structuredClone(db);candidate.adjustments.push(a);validateOperations(candidate);db.adjustments.push(a);return a;}
function recordInventoryAdjustment(){const d=openEditor('Inventory adjustment',select('Product','productId',products().map(p=>[p.id,p.name]))+field('Quantity (negative deducts)','qty','number',-1)+select('Reason','reason',adjustmentReasonOptions().filter(x=>x!=='Warranty Replacement').map(x=>[x,x]))+field('Justification','notes')+field('Date','date','date',today())+field('Total cost of stock deducted','costAmount','number',cents(weightedCosts()[products()[0]?.id]||0)/100)+expenseCostField('Cost treatment','expenseId')+'<p>Confirm the cost for a deduction. Positive adjustments do not create income. Customer returns and warranty replacements belong on their original invoice or claim; do not also adjust the same units here.</p>',f=>commitFinancial('Inventory adjusted',()=>recordAdjustment(f)));const update=()=>{const qty=Number(d.querySelector('[name=qty]').value),id=d.querySelector('[name=productId]').value;d.querySelector('[name=costAmount]').value=qty<0?cents(-qty*(weightedCosts()[id]||0))/100:0;};for(const name of ['qty','productId'])d.querySelector('[name='+name+']').addEventListener('change',update);}
function reviewAdjustmentCost(id){const a=db.adjustments.find(a=>a.id===id);if(!a||a.voided||Number(a.qty)>=0)return;openEditor('Review stock deduction cost',`<p>${html(a.id)} · ${html(pname(a.productId))} · ${html(a.qty)} units</p><p>This confirms cost only. Inventory quantity stays unchanged.</p>`+field('Total cost of units deducted','amount','number',a.costReview?.amount??'')+field('Cost date (blank if unknown)','date','date',a.costReview?.date??a.date??'')+expenseCostField('Cost treatment','expenseId')+field('Explanation / verification','note'),f=>{if(f.amount==='')throw Error('Confirm the cost, using zero only with an explanation.');const review=costEntry(f.amount,f.date,f.expenseId,requiredText(f.note,'Explanation'));return commitFinancial('Inventory deduction cost reviewed',()=>a.costReview=review);},{expenseId:a.costReview?.expenseId||'',note:a.costReview?.note||a.notes||''});}
function openAdjustment(id){const a=db.adjustments.find(a=>a.id===id);if(!a)return;openRecordDialog('Inventory adjustment details',`<p><strong>${html(a.id)}</strong> · ${html(pname(a.productId))}</p><p>${html(a.qty)} units · ${html(a.type||a.reason)} · ${html(a.date||'Date not recorded')}${a.voided?' · Reversed':''}</p><p>${html(a.notes||'')}</p><p>${a.costReview?'Recorded cost '+money(a.costReview.amount)+(a.costReview.expenseId?' · Included in expense '+html(a.costReview.expenseId):''):Number(a.qty)<0?'Cost needs review':'No expense for stock added'}</p><div class="actions">${!a.voided&&Number(a.qty)<0?actionButton('Review cost',`reviewAdjustmentCost(${actionArg(id)})`):''}${!a.voided?actionButton('Reverse incorrect adjustment',`confirmReverseAdjustment(${actionArg(id)})`):''}${actionButton('Inventory history',`openInventoryHistory(${actionArg(a.productId)})`)}</div>`);}
function reverseAdjustment(id,reason){const a=db.adjustments.find(a=>a.id===id);if(!a||a.voided)throw Error('Adjustment is missing or already reversed.');Object.assign(a,{voided:true,voidReason:requiredText(reason,'Reason'),voidedAt:new Date().toISOString()});}
function confirmReverseAdjustment(id){openEditor('Reverse incorrect adjustment',`<p>This reverses the recorded stock change and its separately recorded cost. Any linked expense remains in Expenses. Use only to correct an incorrect entry.</p>${field('Reason','reason')}`,f=>commitFinancial('Inventory adjustment reversed',()=>reverseAdjustment(id,f.reason)),{},'Reverse adjustment');}
function adjustmentLedger(){return `<div class="card"><h3>Inventory adjustments</h3><div class="actions"><button class="primary" onclick="recordInventoryAdjustment()">Record Inventory Adjustment</button><button onclick="openInventoryHistory()">All inventory history</button></div>${db.adjustments.map(a=>`<article class="row"><div><b>${html(pname(a.productId))} · ${html(a.qty)} units</b><p>${html(a.type||a.reason||'Adjustment')} · ${html(a.date||'Date not recorded')}${a.voided?' · Reversed':''}</p></div>${actionButton('Open adjustment',`openAdjustment(${actionArg(a.id)})`)}</article>`).join('')}</div>`;}
function financials(period=reportPeriod){const sales=db.sales.filter(s=>!s.voided&&periodMatch(s.date,period)),returns=allReturns().filter(r=>periodMatch(r.date,period)),payments=cashPayments().filter(p=>periodMatch(p.date||'',period)),expenses=db.expenses.filter(e=>!e.voided&&periodMatch(e.date,period)),wc=weightedCosts(),revenue=(cents(sumMoney(sales,originalSaleTotal))-cents(sumMoney(returns)))/100,cogs=sumMoney(sales,s=>Number(s.qty||0)*(wc[s.productId]||0))-sumMoney(returns,r=>r.qty*(wc[r.productId]||0)),collected=sumMoney(payments),expenseTotal=sumMoney(expenses),costRows=operatingCostRows().filter(r=>periodMatch(costReportDate(r),period)),extra=costRows.filter(r=>!r.expenseId),warrantyProductCost=sumMoney(extra.filter(r=>r.kind==='Warranty products')),warrantyShippingCost=sumMoney(extra.filter(r=>r.kind==='Warranty shipping')),inventoryLossCost=sumMoney(extra.filter(r=>r.type==='adjustment')),additionalCosts=(cents(warrantyProductCost)+cents(warrantyShippingCost)+cents(inventoryLossCost))/100;return {sales,returns,payments,expenses,revenue,cogs,collected,expenseTotal,costRows,warrantyProductCost,warrantyShippingCost,inventoryLossCost,additionalCosts,unreviewedCostCount:pendingCostReviews().length,undatedCostCount:operatingCostRows().filter(r=>!costReportDate(r)&&r.amount>0).length,unitsSold:sales.reduce((n,s)=>n+Number(s.qty||0),0)-returns.reduce((n,r)=>n+r.qty,0),salesTransactions:transactionCount(sales),gross:(cents(revenue)-cents(cogs))/100,net:(cents(revenue)-cents(cogs)-cents(expenseTotal)-cents(additionalCosts))/100};}
function costReviewNotice(f){return f.unreviewedCostCount?`<p class="notice"><strong>Provisional profit estimate:</strong> ${f.unreviewedCostCount} earlier cost record(s) still need review. Those costs are not yet deducted. ${actionButton('Review costs',`openCostReviewQueue()`)}</p>`:'';}
function openCostReviewQueue(){const rows=pendingCostReviews();openRecordDialog('Costs needing review',`<p>Confirm earlier costs before relying on the profit estimate. Reviewing cost does not change inventory quantities.</p>${rows.map(r=>`<section class="movement-row"><strong>${html(r.title)}</strong><p>${html(r.id)} · ${html(r.detail)}</p>${actionButton('Review cost',`${r.type==='claim'?'reviewClaimCosts':'reviewAdjustmentCost'}(${actionArg(r.id)})`)}${actionButton('Open record',`openSource(${actionArg(r.type)},${actionArg(r.id)})`)}</section>`).join('')||'<p>No earlier costs awaiting review.</p>'}`);}
function operatingCostReport(f){return `<div class="card"><h3>Costs beyond sales</h3><p>Expenses already saved are counted once. Separately recorded warranty costs and stock deductions reduce the estimate below. Product costs use the amount confirmed when recorded; sales costs still use the current weighted landed cost. Approved manufacturer credit is not income; applying it to a purchase already reduces landed cost.</p>${costReviewNotice(f)}${reportPeriod!=='All Time'&&f.undatedCostCount?'<p>Costs without dates are included in All Time only. Linked costs follow the date of their expense.</p>':''}<div class="grid g3">${metric('Warranty products · additional',money(f.warrantyProductCost))}${metric('Warranty shipping · additional',money(f.warrantyShippingCost))}${metric('Stock losses / non-sale use · additional',money(f.inventoryLossCost))}</div>${f.costRows.filter(r=>r.amount>0).map(r=>`<section class="movement-row"><strong>${html(r.kind)} · ${money(r.amount)}</strong><p>${html(r.id)} · ${html(costReportDate(r)||'Date not recorded')} · ${r.expenseId?'Already included in expense '+html(r.expenseId):'Deducted separately'}</p>${actionButton('Open record',`openSource(${actionArg(r.type)},${actionArg(r.id)})`)}</section>`).join('')||'<p>No confirmed additional costs in this period.</p>'}</div>`;}
function exportOperatingCosts(){downloadCSV('operating-costs',['Category','Record','Date','Amount','Included In Expense','Explanation'],operatingCostRows().map(r=>[r.kind,r.id,r.date,r.amount,r.expenseId,r.note]));}

// New optional fields are validated without rewriting any legacy records.
function validateOperations(data){
 const fail=message=>{throw Error(message+' needs review.');},validCost=x=>{if(!x||typeof x!=='object'||Array.isArray(x)||typeof x.amount!=='number'||!Number.isFinite(x.amount)||x.amount<0||Math.abs(x.amount*100-Math.round(x.amount*100))>0.00001||typeof x.date!=='string'||optionalDate(x.date)!==x.date||typeof x.expenseId!=='string'||typeof x.note!=='string')fail('Recorded operating cost');};
 for(const o of data.orders||[])if(o.receipts!==undefined){if(!Array.isArray(o.receipts))fail('Purchase receipt history');const ids=new Set(),totals=new Map();for(const r of o.receipts){if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||typeof r.date!=='string'||!r.date||paymentDate(r.date)!==r.date||!Array.isArray(r.lines)||!r.lines.length)fail('Purchase receipt');ids.add(r.id);const indexes=new Set();for(const l of r.lines){if(!l||!Number.isSafeInteger(l.lineIndex)||l.lineIndex<0||indexes.has(l.lineIndex)||o.lines?.[l.lineIndex]?.productId!==l.productId||!Number.isSafeInteger(l.qty)||l.qty<=0)fail('Purchase receipt quantity');indexes.add(l.lineIndex);totals.set(l.lineIndex,(totals.get(l.lineIndex)||0)+l.qty);}}for(const [i,qty] of totals)if(qty>Number(o.lines[i].received||0))fail('Purchase receipts above received stock');}
 for(const c of data.claims||[]){if(c.operationsVersion!==undefined&&c.operationsVersion!==1)fail('Warranty tracking version');if(c.costReview!==undefined){validCost(c.costReview?.product);validCost(c.costReview?.shipping);}if(c.replacementEvents!==undefined){if(!Array.isArray(c.replacementEvents))fail('Replacement history');const ids=new Set();let qty=c.replacementSent?Number(c.qty||0):0;for(const r of c.replacementEvents){if(!r||typeof r.id!=='string'||!r.id||ids.has(r.id)||!Number.isSafeInteger(r.qty)||r.qty<=0||!['inventory','supplier-direct'].includes(r.source)||typeof r.date!=='string'||!r.date||paymentDate(r.date)!==r.date||typeof r.notes!=='string'||!r.notes.trim()||r.voided!==undefined&&typeof r.voided!=='boolean')fail('Replacement entry');ids.add(r.id);validCost(r.productCost);validCost(r.shippingCost);if(typeof r.unitCost!=='number'||!Number.isFinite(r.unitCost)||r.unitCost<0||cents(r.unitCost*r.qty)!==cents(r.productCost.amount)||r.productCost.date!==r.date||r.shippingCost.date!==r.date)fail('Replacement costs');if(!r.voided)qty+=r.qty;}if(qty>Number(c.qty||0))fail('Replacement quantity above claim quantity');}}
 for(const a of data.adjustments||[])if(a.costReview!==undefined){if(Number(a.qty)>=0)fail('Cost on a positive stock adjustment');validCost(a.costReview);}
 validateCostLinks(data);
}

// Never guess which historical record a warning belongs to.
function reviewCollection(x){return x.type==='sale'?db.sales:x.type==='warranty'?db.claims:x.type==='inventory'?db.orders:[];}
function reviewRecord(x){
 const rows=reviewCollection(x),id=x.recordId||(x.type==='sale'?x.saleId:x.type==='warranty'?x.claimId:x.orderId);
 if(id)return rows.find(r=>r.id===id)||null;
 if(x.row!==undefined&&x.row!==null&&String(x.row)!==''){const matches=rows.filter(r=>r.sourceRow!==undefined&&String(r.sourceRow)===String(x.row));return matches.length===1?matches[0]:null;}
 return null;
}
function reviewType(x){return x.type==='sale'?'sale':x.type==='warranty'?'claim':x.type==='inventory'?'order':'';}
function openReviewRecord(i){const x=db.reviewQueue?.[i],r=x&&reviewRecord(x);if(!r)return chooseReviewRecord(i);openSource(reviewType(x),r.id);}
function chooseReviewRecord(i){const x=db.reviewQueue?.[i];if(!x)return;const rows=reviewCollection(x);if(!rows.length)return alert('No matching record type is available. Keep this warning for review with your original records.');openEditor('Choose the record to review',`<p>${html(reviewTitle(x))} · ${html(x.customer||'')}</p><p>This warning has no unique verified link. Match the invoice or claim against your original records. No date, quantity or balance will change when you save the link.</p>`+select('Exact record','recordId',[['','Choose a record'],...rows.map(r=>[r.id,r.id+' · '+(r.customer||r.maker||'')+' · '+(r.productId?pname(r.productId):'Purchase order')+' · '+(r.date||r.purchaseDate||'Date not recorded')])])+field('Why this is the matching record','reason'),f=>{if(!rows.some(r=>r.id===f.recordId))throw Error('Choose the exact affected record.');const reason=requiredText(f.reason,'Reason');return commitFinancial('Review warning linked',()=>Object.assign(x,{recordId:f.recordId,linkReason:reason,linkedAt:new Date().toISOString()}));},{},'Save record link');}
function reviewDetails(x){const r=reviewRecord(x);return [{label:'Record',value:r?.id||'Choose the matching record'},{label:x.type==='inventory'?'Manufacturer':'Customer',value:r?.customer||r?.maker||x.customer||'Not recorded'},...(r?.productId?[{label:'Product',value:pname(r.productId)}]:[]),...(x.type==='sale'?[{label:'Quantity',value:r?.qty??'Not recorded'},{label:'Unit price',value:r?money(r.unitPrice):'Not recorded'}]:[]),{label:'Current date',value:(x.type==='inventory'?(r?.purchaseDate||r?.date):r?.date)||'Not recorded'},{label:'Reason for review',value:reviewTitle(x)}];}
function editRecordDate(type,id){const rows=type==='sale'?db.sales:type==='claim'?db.claims:db.orders,r=rows.find(r=>r.id===id);if(!r)return;const key=type==='order'?'purchaseDate':'date';openEditor('Confirm record date',`<p>${html(r.id)} · ${html(r.customer||r.maker||'')}</p>`+field(type==='order'?'Actual purchase date (blank if unknown)':'Date (blank if unknown)','date','date',r[key]||(type==='order'?r.date:'')||'')+'<p>Use the actual transaction date. Expected arrival and stock receipt dates are separate.</p>',f=>{const date=optionalDate(f.date);return commitFinancial('Record date corrected',()=>r[key]=date);});}
function resolveReview(i,f){
 const x=db.reviewQueue?.[i],r=x&&reviewRecord(x);if(!x||!r)throw Error('Link this warning to the exact record first.');if(x.resolved||x.ignored)throw Error('This review item is already closed.');
 if(reviewTitle(x)==='Sale Quantity Needs Review'){
  if(r.voided||(r.returns||[]).length)throw Error('This invoice is voided or has return history. Open the invoice and review those entries before correcting quantity.');const qty=whole(f.qty,'Quantity'),old=r.qty,shortfall=spentCreditShortfall(r.id);r.qty=qty;if(spentCreditShortfall(r.id)>shortfall){r.qty=old;throw Error('This quantity change would leave credit already applied or refunded unfunded. Review those credit movements first.');}x.resolution='Quantity confirmed: '+qty;
 }else if(['Sale Date Missing','Warranty Date Needs Confirmation','Purchase Date Missing'].includes(reviewTitle(x))){const date=optionalDate(f.date);r[x.type==='inventory'?'purchaseDate':'date']=date;x.resolution=date?'Date confirmed':'Date remains unknown';}
 else x.resolution=requiredText(f.note,'Resolution note');
 x.resolved=true;x.resolvedAt=new Date().toISOString();
}
function editReview(i){const x=db.reviewQueue?.[i];if(!x)return;const r=reviewRecord(x);if(!r)return chooseReviewRecord(i);const title=reviewTitle(x),body=title==='Sale Quantity Needs Review'?field('Confirmed original quantity','qty','number',r.qty):['Sale Date Missing','Warranty Date Needs Confirmation','Purchase Date Missing'].includes(title)?field('Confirmed actual date (blank keeps unknown)','date','date',(x.type==='inventory'?r.purchaseDate||r.date:r.date)||''):field('Resolution note','note');openEditor(title,`<p><strong>${html(r.id)}</strong> · ${html(r.customer||r.maker||'')}</p>`+body,f=>commitFinancial('Review item resolved',()=>resolveReview(i,f)));}
function approveUnknown(i){const x=db.reviewQueue?.[i];if(!x||x.resolved||x.ignored)return;return commitFinancial('Review item kept unknown',()=>{x.resolved=true;x.resolution='Kept unknown after review';x.resolvedAt=new Date().toISOString();});}
function integrityChecks(){
 const issues=[];for(const s of db.sales.filter(s=>!s.voided)){if(!s.date)issues.push({type:'sale',recordId:s.id,area:'Sales',text:s.id+' · '+s.customer+' — sale date missing'});if(!Number.isSafeInteger(Number(s.qty))||Number(s.qty)<=0)issues.push({type:'sale',recordId:s.id,area:'Sales',text:s.id+' — quantity needs review'});}
 for(const p of inventory())if(p.onHand<0)issues.push({type:'product',recordId:p.id,area:'Inventory',text:p.name+' — '+p.onHand+' on hand. Review its stock movements.'});
 for(const o of db.orders.filter(o=>!o.cancelled))if((o.lines||[]).some(l=>Number(l.received||0)>Number(l.qty||0)))issues.push({type:'order',recordId:o.id,area:'Purchase Orders',text:o.id+' — received quantity exceeds ordered quantity'});
 for(const p of db.payments.filter(p=>!p.voided))if(!db.sales.some(s=>s.id===p.saleId&&!s.voided))issues.push({type:'payment',recordId:p.id,area:'Payments',text:p.id+' — linked invoice is missing or voided'});
 for(const r of pendingCostReviews())issues.push({type:r.type,recordId:r.id,area:'Costs',text:r.id+' — '+r.title});return issues;
}
function reviewHealth(type,id){openSource(type,id);}
function integrityView(){const issues=integrityChecks(),low=lowStockRows();return `<div class="card hero"><h1>Data Health</h1><p>Checks open the affected record. Nothing is changed until you save a correction.</p></div><div class="grid g3">${metric('Items to review',issues.length)}${metric('Low-stock products',low.length)}${metric('Active review items',reviewRows().length)}</div><div class="card"><h3>Items to review</h3>${empty(issues)}${issues.map(x=>`<article class="row"><div><b>${html(x.area)}</b><p>${html(x.text)}</p></div>${actionButton('Open record',`reviewHealth(${actionArg(x.type)},${actionArg(x.recordId)})`)}</article>`).join('')}</div><div class="card"><h3>Low stock</h3>${empty(low)}${low.map(x=>`<article class="row"><div><b>${html(x.name)}</b><p>Alert at ${lowThreshold(x.id)} · ${x.onHand} on hand</p></div><div class="actions">${actionButton('Inventory history',`openInventoryHistory(${actionArg(x.id)})`)}${actionButton('Stock alert',`reviewLowStock(${actionArg(x.id)})`)}</div></article>`).join('')}</div>`;}
